import * as fs from "fs";
export function icf2ld(icfContent, outPath) {
    const symbols = {};
    const lines = icfContent.split("\n");
    for (const line of lines) {
        const trimmed = line.trim();
        const defineMatch = trimmed.match(/^define\s+symbol\s+(\w+)\s*=\s*(0x[0-9A-Fa-f]+);?$/);
        if (defineMatch) {
            symbols[defineMatch[1]] = defineMatch[2];
        }
    }
    const romStart = symbols["__ICFEDIT_region_ROM_start__"] || "0x08000000";
    const romEnd = symbols["__ICFEDIT_region_ROM_end__"] || "0x081FFFFF";
    const ramStart = symbols["__ICFEDIT_region_RAM_start__"] || "0x20000000";
    const ramEnd = symbols["__ICFEDIT_region_RAM_end__"] || "0x2000FFFF";
    const intVec = symbols["__ICFEDIT_intvec_start__"] || romStart;
    const romLength = parseInt(romEnd, 16) - parseInt(romStart, 16);
    const ramLength = parseInt(ramEnd, 16) - parseInt(ramStart, 16);
    const ldScript = `/* Generated by iar2cmake from IAR .icf file */
MEMORY
{
  FLASH (rx)  : ORIGIN = ${romStart}, LENGTH = ${romLength}
  RAM   (rwx) : ORIGIN = ${ramStart}, LENGTH = ${ramLength}
}

_estack = ORIGIN(RAM) + LENGTH(RAM);

SECTIONS
{
  .isr_vector : {
    KEEP(*(.isr_vector))
  } > FLASH

  .text : {
    *(.text*)
    *(.rodata*)
    . = ALIGN(4);
    _etext = .;
  } > FLASH

  .data : {
    _sdata = .;
    *(.data*)
    . = ALIGN(4);
    _edata = .;
    _sidata = LOADADDR(.data);
  } > RAM AT > FLASH

  .bss : {
    _sbss = .;
    *(.bss*)
    *(COMMON)
    . = ALIGN(4);
    _ebss = .;
  } > RAM

  ._user_heap_stack : {
    . = ALIGN(8);
    . = . + ${symbols["__ICFEDIT_size_heap__"] || "0x200"};
    . = . + ${symbols["__ICFEDIT_size_cstack__"] || "0x400"};
    . = ALIGN(8);
  } > RAM
}
`;
    fs.writeFileSync(outPath, ldScript, "utf-8");
}
